import{_ as i,o as n,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Stationen","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station/stations.md","filePath":"de/repair-station/stations.md"}'),a={name:"de/repair-station/stations.md"};function o(s,e,d,l,u,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="stationen" tabindex="-1">Stationen <a class="header-anchor" href="#stationen" aria-label="Permalink to &quot;Stationen&quot;">​</a></h1><p>Eine Station ist eine Haltezone für Fahrzeuge mit einem Radius, einem Preisprozentsatz und, wenn du willst, einem Prop wie einer daneben stehenden Werkzeugkiste. Drei Stationen sind bereit: <strong>Hayes Autos</strong>, <strong>Sandy Shores</strong> und <strong>Paleto Bay</strong>.</p><h2 id="so-lauft-eine-reparatur-ab" tabindex="-1">So läuft eine Reparatur ab <a class="header-anchor" href="#so-lauft-eine-reparatur-ab" aria-label="Permalink to &quot;So läuft eine Reparatur ab&quot;">​</a></h2><ol><li>Der Fahrer hält im Radius der Station an. Ein Hinweis zeigt den niedrigsten Preis.</li><li><strong>E</strong> öffnet das Reparaturmenü mit dem Schaden des Fahrzeugs und den Leistungen samt Preisen (Job-Rabatte und Stationsprozentsatz inklusive).</li><li>Der Preis wird bezahlt, der Motor geht aus und die Haube öffnet sich. Ein Fortschrittsbalken läuft für die Dauer der Leistung, mit Ton und Funken. Drücke <strong>X</strong> zum Abbrechen.</li><li>Am Ende sind die reparierten Teile in Ordnung und das Fahrzeug kann wegfahren.</li></ol><p>Die Station lehnt die Reparatur ab, wenn:</p><ul><li>die Station geschlossen ist oder <code>Enabled</code> aus ist;</li><li>der Spieler das Fahrzeug nicht fährt oder das Fahrzeug nicht im Bereich der Station ist;</li><li>das Fahrzeug fährt;</li><li>die Station schon belegt ist (ein Fahrzeug zugleich);</li><li>die Fahrzeugklasse gesperrt ist (<code>BlockedClasses</code>);</li><li>die Leistung an diesem Fahrzeug nichts repariert und <code>RequireDamage</code> an ist;</li><li>der Spieler die Wartezeit abwarten muss (<code>CooldownSeconds</code>);</li><li>Mechaniker im Dienst sind, siehe unten;</li><li>der Spieler nicht zahlen kann.</li></ul><p>Verlässt der Spieler das Fahrzeug, fährt weg oder bricht ab, oder wird die Station während der Reparatur geschlossen oder gelöscht, stoppt die Reparatur und der Spieler bekommt den abgebuchten Betrag auf das belastete Konto zurück.</p><h2 id="mechaniker-im-dienst" tabindex="-1">Mechaniker im Dienst <a class="header-anchor" href="#mechaniker-im-dienst" aria-label="Permalink to &quot;Mechaniker im Dienst&quot;">​</a></h2><p>Spieler, die eine Werkstatt führen, sollen ihre Kunden nicht an eine Station verlieren. Trage ihre Jobs in <code>MechanicJobs</code> ein und stelle <code>MaxMechanicsOnDuty</code> ein: Solange so viele Mechaniker oder mehr im Dienst sind, sind alle Stationen geschlossen und weisen die Spieler an, sie zu rufen. Mit <code>0</code> schließen die Stationen aus diesem Grund nie.</p><h2 id="der-stationseditor" tabindex="-1">Der Stationseditor <a class="header-anchor" href="#der-stationseditor" aria-label="Permalink to &quot;Der Stationseditor&quot;">​</a></h2><p>Öffne ihn mit <code>/nay:repair</code> oder mit <strong>Stationen verwalten</strong> auf der Seite Repair Station in <code>/nay</code>. Er braucht den Scope <code>nay_repair.config</code>.</p><ol><li><strong>Neue Station hier</strong>: Stelle dich dorthin, wo Fahrzeuge halten sollen, im Fahrzeug oder zu Fuß. Die Station übernimmt deine Position und Ausrichtung.</li><li>Wähle die Fahrzeugposition oder die Prop-Position und verschiebe sie: <ul><li>Pfeiltasten: vor, zurück, links, rechts, relativ zur Kamera;</li><li>Bild auf / Bild ab: Höhe;</li><li>Q / E: drehen;</li><li>Umschalt: feine Schritte.</li></ul></li><li><strong>Zu meiner Position</strong> und <strong>Auf den Boden</strong> setzen das gewählte Element.</li><li>Lege Name, Radius, Preisprozentsatz, Blip und Prop fest. Vorgeschlagene Props: <code>prop_toolchest_05</code>, <code>prop_toolchest_01</code>, <code>prop_carcreeper</code>, <code>prop_compressor_03</code> oder ein beliebiger Modellname.</li><li><strong>Eingabe</strong> speichert, <strong>Rücktaste</strong> bricht ab. Die Station ist sofort für alle Spieler aktiv.</li></ol><p>Die Verwaltung kann außerdem zu einer Station gehen, sie öffnen oder schließen und löschen (zweimal drücken zum Bestätigen). Der Editor füllt die Einstellung <code>Stations</code>, beschrieben auf der Seite <a href="/de/repair-station/settings#stations">Einstellungen</a>. Jede Station erhält eine Kennung, die sich nie ändert.</p>',13)])])}const p=i(a,[["render",o]]);export{g as __pageData,p as default};
